// Direct-Mapped Cache Parameters (Example)
const int CACHE_SIZE = 4096;    // 4KB
const int BLOCK_SIZE = 64;      // 64 Bytes
const int NUM_LINES = CACHE_SIZE / BLOCK_SIZE;

// Address Decomposition constants (32-bit address)
const int OFFSET_BITS = 6;  // log2(64)
const int INDEX_BITS = 6;   // log2(64)
const int TAG_SHIFT = OFFSET_BITS + INDEX_BITS;

unsigned int M_ADDR = 0x00A3412C; // Memory address

// Direct Mapping Calculation
unsigned int offset = M_ADDR & ((1 << OFFSET_BITS) - 1);
unsigned int index  = (M_ADDR >> OFFSET_BITS) & ((1 << INDEX_BITS) - 1);
unsigned int tag    = M_ADDR >> TAG_SHIFT;

